import{esc,button,input,select}from'../phase4/ui.js';
import{parse,rational,fmt,approx,mul,squareVsTwo}from'./b09-math.js';
import{currentCount,jumpEnd,algebra,bounds,divisionState,powerSize}from'./b09-model.js';
const f=(key,label,v)=>input(key,esc(label),v,'autocomplete="off" spellcheck="false"');
const range=(key,label,v,min,max,step=1)=>`<label class="field">${esc(label)}<input type="range" data-xfield="${key}" aria-label="${esc(label)}" min="${min}" max="${max}" step="${step}" value="${v}"><output data-xvalue="${key}">${v}</output></label>`;
const placeSlider=(key,label,p,min,max)=>`<label class="field">${esc(label)}<input type="range" data-xfield="${key}" aria-label="${esc(label)}" min="${min*100}" max="${max*100}" step="${Number.isInteger(min)&&Number.isInteger(max)?25:1}" value="${p}"><span class="muted">左右移动，按方向键可微调</span></label>`;
const rel=(k,label,v)=>select(k,label,v,[['<','小于 <'],['=','等于 ='],['>','大于 >']]);
const zero=m=>select('zero','这个情境里的0表示什么',m.zero,[['reference','选定的参照：从这里分出两边'],['nothing','什么都没有，也没有数可以再往左']]);
function axis(min,max,points=[],jumps=[],{sparse=false,shade=null,ends=null}={}){const x=v=>50+(v-min)/(max-min)*740,step=max-min<=20?1:max-min<=40?2:10,ticks=[];for(let v=Math.ceil(min/step)*step;v<=max;v+=step)ticks.push(v);const labelTicks=sparse?[min,max]:ticks;return`<svg class="b9-axis" viewBox="0 0 840 180" role="img" aria-label="${min}到${max}的等距数轴"><defs><marker id="b9-tip" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#b27143"/></marker></defs><path d="M50 118H790"/>${shade?`<path class="b9-band" d="M${x(shade.a)} 118H${x(shade.b)}"/>`:''}${labelTicks.map(v=>`<path d="M${x(v)} 111v15"/><text x="${x(v)}" y="155">${esc(ends?(v===min?ends[0]:ends[1]):v)}</text>`).join('')}${min<=0&&max>=0?`<path class="b9-zero" d="M${x(0)} 100v35"/>`:''}${jumps.map((j,i)=>{const h=32+(i%3)*20;return`<path class="b9-jump" marker-end="url(#b9-tip)" d="M${x(j.a)} 114Q${(x(j.a)+x(j.b))/2} ${h} ${x(j.b)} 111"/><text class="b9-jump-label" x="${(x(j.a)+x(j.b))/2}" y="${h+24}">${esc(j.label)}</text>`;}).join('')}${points.map((p,i)=>`<circle class="b9-point ${p.open?'open':''}" cx="${x(p.v)}" cy="118" r="6"/><text class="b9-point-label" x="${Math.max(57,Math.min(783,x(p.v)))}" y="${i%2?92:18}">${esc(p.label??p.v)}</text>`).join('')}</svg>`;}
const hops=(start,steps)=>{let p=start;return steps.map(n=>{const v={a:p,b:p+n,label:(n>0?'+':'')+n};p+=n;return v;});};
const tools=(m)=>`<div class="b9-tools">${[['line','↔ 数轴'],['hundred','▦ 百数表'],['cubes','● 小珠子'],['ruler','▏短尺'],['stick','▏米尺']].map(([v,l])=>button('tool-select',l,`data-value="${v}" aria-pressed="${m.tool===v}"`)).join('')}</div>`;
function ruler(t,m){const cap=m.tool==='stick'?100:30,long=t.length>30,scale=long?1:cap===100?4.3:8.5,pos=v=>long?350-v*scale:40+v*scale;return long?`<svg class="b9-measure" viewBox="0 0 600 390" aria-label="模拟门高与可移动米尺"><rect class="object door" x="200" y="${pos(t.start+t.length)}" width="110" height="${t.length*scale}"/><text x="220" y="30">模拟门高</text>${m.segments.map((s,i)=>`<path class="b9-band" d="M${320+i*8} ${pos(s.zero)}V${pos(s.zero+s.length)}"/><text x="420" y="${pos(s.zero+s.length/2)+5}">${s.length}厘米</text>`).join('')}<path class="ruler" d="M350 ${pos(m.zero)}V${pos(m.zero+cap)}"/>${Array.from({length:cap/10+1},(_,i)=>`<path d="M345 ${pos(m.zero+i*10)}h14"/>${i%2?'':`<text x="377" y="${pos(m.zero+i*10)+5}">${i*10}</text>`}`).join('')}<path class="b9-band" d="M355 ${pos(m.zero)}V${pos(m.zero+m.length)}"/><text x="385" y="375">厘米</text></svg>`:`<svg class="b9-measure" viewBox="0 0 700 170" aria-label="模拟丝带和短尺"><rect class="object ribbon" x="${pos(t.start)}" y="25" width="${t.length*scale}" height="28"/><text x="${pos(t.start)}" y="18">模拟丝带</text><path class="ruler" d="M${pos(m.zero)} 85h${cap*scale}"/>${Array.from({length:cap+1},(_,i)=>`<path d="M${pos(m.zero+i)} 78v${i%5?10:19}"/>${i%5?'':`<text x="${pos(m.zero+i)}" y="118">${i}</text>`}`).join('')}<path class="b9-band" d="M${pos(m.zero)} 85h${m.length*scale}"/><text x="620" y="118">厘米</text></svg>`;}
function proof(card){if(card.why==='root2')return'假如√2能写成已经约到最简的a/b，就有a²=2b²，所以a是偶数（奇数平方仍是奇数）。代回去可得b也是偶数。两者还能同时除以2，与已经最简矛盾。它不能写成整数之比，小数也就不会终止或循环。这段理由可以用自己的话再讲一遍，系统只保存解释。';if(card.why==='pi')return'π不能写成两个整数之比，是已有严格证明的数学事实；这里不展示完整证明。3.14只是它的近似值。屏幕上看到多少位，都不能用来证明它是否循环。';if(card.why==='root9')return'3×3=9，所以√9的值是3，也就是3/1。根号本身不决定一个数属于哪一类。';return'有限小数可按位写成整数分数；循环小数也可以。刚才的分份活动把余数回来与数字重复联系起来，不能因为数字写得长就说它不是分数。';}
export function visual(t,m){switch(t.type){
 case'x-signedline':return(t.mode==='walk'?`<p class="b9-caption">${[t.start,...m.hops].join(' → ')}</p>`+axis(t.min,t.max,[{v:currentCount(t,m),label:'现在 '+currentCount(t,m)}]):axis(t.min,t.max,m.positions.map((p,i)=>({v:p/100,label:m.touched[i]?t.values[i]:'?'}))))+`<p class="muted">相邻等长间隔表示相同的差；零也是一站。</p>`;
 case'x-directedjump':return`<p class="b9-caption">${t.context?t.context+' · ':''}${t.start} ${t.op==='+'?'＋':'−'} (${t.operand}) ${m.committed===null?'':' · 先前猜 '+esc(m.committed)}</p>`+axis(t.min,t.max,[{v:m.anchor,label:'起点 '+m.anchor},{v:jumpEnd(t,m),label:'到达 '+jumpEnd(t,m)}],hops(m.anchor,m.jumps),{sparse:t.sparse})+(t.reverse?`<p class="b9-caption">括号里的变化：从0到 ${m.refSaved??'？'}；减去它，要反向撤销。</p>`+axis(t.min,t.max,[],m.refSaved===null?[]:[{a:0,b:m.refSaved,label:'要撤销的变化'}],{sparse:true}):'');
 case'x-zerodistance':return axis(t.min,t.max,m.positions.map((p,i)=>({v:p/100,label:m.touched[i]?t.values[i]:'?'})),m.positions.flatMap((p,i)=>m.traced.some(s=>s.index===i&&s.point===p)?[{a:0,b:p/100,label:'距离 '+Math.abs(p/100)}]:[]))+`<p class="b9-caption">位置有左右，走回零的距离没有负数。</p>`;
 case'x-allowedrange':{const a=algebra(t,m),shade=m.side==='right'?{a:m.boundary,b:t.max}:m.side==='left'?{a:t.min,b:m.boundary}:m.side==='between'&&m.boundary<=m.other?{a:m.boundary,b:m.other}:null;return(t.algebra?`<p class="b9-equation">${fmt(a.a)} × 盒子 ${a.b[0]<0?'−':'＋'} ${fmt([Math.abs(a.b[0]),a.b[1]])} ${esc(t.relation)} ${fmt(a.rhs)}</p><p class="muted">两边做同样的事；这里除数只用正数。</p>`:'')+axis(t.min,t.max,[{v:m.boundary,label:'边界 '+m.boundary,open:m.closed!=='yes'},...(t.relation==='between'?[{v:m.other,label:'另一端 '+m.other,open:m.otherClosed!=='yes'}]:[])],[],{shade})+`<p class="b9-caption">${m.side==='right'?'→ 向右一直延伸':m.side==='left'?'← 向左一直延伸':m.side==='between'?'两端之间的所有数':'选一边或一整段'} · ● 包括　○ 不包括</p><div class="b9-records">${m.trials.map(p=>`<span>试 ${esc(p.value)}：原要求${p.actual?'允许':'不允许'} / 画的范围${p.graph?'允许':'不允许'}</span>`).join('')}</div>`;}
 case'x-toolwork':return tools(m)+(t.mode==='calculate'?m.tool==='line'?axis(0,100,[{v:t.start,label:'起点 '+t.start},{v:t.start+m.line.reduce((a,b)=>a+b,0),label:'现在'}],hops(t.start,m.line)):m.tool==='hundred'?`<div class="b9-hundred">${Array.from({length:100},(_,i)=>`<span class="${i+1===t.start+m.grid.reduce((a,b)=>a+b,0)?'on':''}">${i+1}</span>`).join('')}</div><p class="muted">往下一排加10，往右一格加1；数表有位置，数值仍连续。</p>`:'<p class="b9-caption">试试数轴的跳跃，或百数表的十与一。</p>':t.mode==='small'?`<div class="b9-beads"><section><b>红珠</b>${Array.from({length:m.red},()=>'<i></i>').join('')}</section><section><b>蓝珠</b>${Array.from({length:m.blue},()=>'<i></i>').join('')}</section></div>`:['ruler','stick'].includes(m.tool)?ruler(t,m)+`<p class="muted">按比例绘制的模拟量尺，屏幕尺寸不是实际厘米。已留下 ${m.segments.map(s=>s.length+'厘米').join(' + ')||'0段'}。</p>`:'<p class="b9-caption">选一件能量长度的工具。短尺30厘米，米尺100厘米。</p>');
 case'x-powerbuild':return(t.pow===2?`<div class="b9-square" style="--n:${m.side}">${Array.from({length:powerSize(t,m)},(_,i)=>button('power-cell','',`data-index="${i}" class="${m.filled.includes(i)?'on':''}" aria-label="第${i+1}块" ${m.committed===null?'disabled':''}`)).join('')}</div>`:'')+`<p class="b9-caption">每边 ${m.side} · 已搭 ${m.filled.length} 块${t.target?' / 目标 '+t.target+' 块':''}</p><p class="b9-equation">${m.factors.join(' × ')||'把相同的边长逐个放进乘式'}</p>`;
 case'x-powerchain':return`<div class="b9-chain"><span>1</span>${m.products.map(v=>`<b>× ${t.base} →</b><span>${v}</span>`).join('')}${m.added?`<b>＋ ${t.add} →</b><span>${m.products.at(-1)+t.add}</span>`:''}</div><p class="b9-caption">已放 ${m.products.length} / ${t.count} 个因子 ${t.base}</p>`;
 case'x-rootwindow':{const w=m.windows.at(-1)||{a:[1,1],b:[2,1]};return axis(approx(w.a),approx(w.b),[{v:Math.sqrt(2),label:'√2 的位置（示意）'}],[],{sparse:true,ends:[fmt(w.a),fmt(w.b)]})+`<div class="b9-records">${m.windows.map(w=>`<span>${fmt(w.a)} 的平方 < 2 < ${fmt(w.b)} 的平方</span>`).join('')}</div><p class="muted">数轴位置用于显示；两端是否夹住2用精确分数比较。最近一次：${m.trials.length?(m.trials.at(-1).kept?'留住了更小的一段':'还不能用这段：检查两端的平方和大小'):'从1到2开始'}</p>`;}
 case'x-decimalmachine':{const s=divisionState(t,m);return`<p class="b9-caption">${t.n} ÷ ${t.d} · 已写出 ${Math.floor(t.n/t.d)}.${s.digits.join('')||'?'}</p><div class="b9-division"><strong>当前余数 ${s.r}</strong><span>拆成十份 → ${s.r*10} 个更小的单位</span><div>${Array.from({length:t.d},()=>`<i>分到一份</i>`).join('')}</div></div><div class="b9-records">${m.steps.map((st,i)=>`<span>第${i+1}位：${st.digit} · 留余数 ${st.rem}</span>`).join('')}</div><p class="muted">0表示分完；同一个非零余数回来，后续会重新走一样的路。这里显示的是已分出的位数。</p>`;}
 case'x-numbercards':{const c=t.cards[m.active];return`<div class="b9-tabs">${t.cards.map((c,i)=>button('number-card',String(i+1),`data-index="${i}" aria-label="第${i+1}张数卡" aria-pressed="${i===m.active}"`)).join('')}</div><p class="b9-number-card">${esc(c.label)}</p>${button('number-basis','看看这张卡的依据')}${m.basis.includes(m.active)?`<p class="b9-basis">${proof(c)}</p>`:''}`;}
 case'x-betweenpoints':{const{a,b}=bounds(t,m);return`<p class="b9-caption">放大了 ${m.history.length} 次 · ${fmt(a)} 与 ${fmt(b)}</p>`+axis(approx(a),approx(b),m.pending?[{v:approx(m.pending),label:fmt(m.pending)}]:[],[],{sparse:true,ends:[fmt(a),fmt(b)]})+`<p class="b9-caption">${m.pending?'新的中间点：'+fmt(m.pending):'在两端之间，自己放一个新点'}</p><p class="muted">${esc(m.issue)||'分数也可以输入，例如7/24。两端不同，取平均数就能在中间找到新数。'}${m.history.length>=8?' 本画布演示到8次，数学上的取中点仍可继续。':''}</p>`;}
}return'';}
export function controls(t,m){switch(t.type){
 case'x-signedline':return t.mode==='walk'?f('next','下一站写多少',m.next)+button('signed-step','把这一站留下')+button('signed-undo','取回最后一站'):t.values.map((v,i)=>placeSlider('positions.'+i,'移动 '+v,m.positions[i],t.min,t.max)).join('')+(t.compare?rel('relation',`${t.values[t.compare[0]]} 与 ${t.values[t.compare[1]]} 比较`,m.relation):'')+(t.zero?zero(m):'');
 case'x-directedjump':return range('anchor','先把起点放好',m.anchor,t.min,t.max)+(m.committed===null?f('guess','先猜走到哪里',m.guess)+button('direct-predict','留下猜想，再画变化'):(t.reverse?range('reference','先表示括号里的变化，从0到哪里',m.reference,t.min,t.max)+button('direct-reference','留下这段要撤销的变化'):'')+`<div class="b9-fields">${f('size','这一次跳多远（填正的长度）',m.size)}${select('dir','这一次朝哪边',m.dir,[['left','向左 ←'],['right','向右 →']])}</div>`+button('direct-jump','画出这一跳')+button('direct-undo','取回最后一跳')+f('answer','最后到达哪里',m.answer)+(t.zero?zero(m):''));
 case'x-zerodistance':return t.values.map((v,i)=>`<div class="b9-distance-row">${placeSlider('positions.'+i,'移动 '+v,m.positions[i],t.min,t.max)}${button('distance-trace','描出这个点到零的距离',`data-index="${i}"`)}${f('answers.'+i,'这个点离零多远',m.answers[i])}</div>`).join('')+(t.compare?rel('numberRelation','−8 与 −3 的数值比较',m.numberRelation)+rel('distanceRelation','欠8元与欠3元，欠款大小比较',m.distanceRelation):'');
 case'x-allowedrange':return(t.algebra?`<div class="b9-fields">${select('operation','两边一起',m.operation,[['sub','减去同一个数'],['div','除以同一个正数']])}${f('amount','用哪个数',m.amount)}</div>${button('range-operation','两边一起做')}${button('range-undo','退回上一步')}`:'')+range('boundary','移动边界',m.boundary,t.min,t.max,.5)+select('side','哪些位置都可以',m.side,[['left','边界左边'],['right','边界右边'],['between','两端之间']])+select('closed','这个边界本身算不算',m.closed,[['yes','算 · 实心点'],['no','不算 · 空心点']])+(t.relation==='between'?range('other','移动另一端',m.other,t.min,t.max,.5)+select('otherClosed','另一端本身算不算',m.otherClosed,[['yes','算 · 实心点'],['no','不算 · 空心点']]):'')+f('statement','用x写出可选范围，可以用 >= 或 <=',m.statement)+f('probe','试一个数：边界、里面与外面都试试',m.probe)+button('range-test','把这个数放进去试');
 case'x-toolwork':return(t.mode==='calculate'&&['line','hundred'].includes(m.tool)?`<div class="b9-actions">${[-10,-1,1,10].map(d=>button('tool-move',d>0?'＋'+d:String(d),`data-delta="${d}"`)).join('')}</div>`:t.mode==='small'?`<div class="b9-actions">${['red','blue'].flatMap(c=>[-1,1].map(d=>button('tool-bead',(c==='red'?'红珠':'蓝珠')+(d>0?'＋':'−'),`data-color="${c}" data-delta="${d}"`))).join('')}</div>`:t.mode==='measure'&&['ruler','stick'].includes(m.tool)?range('zero','移动尺的零刻度',m.zero,0,t.length>30?220:40)+range('length','这一段量到尺上的几厘米',m.length,0,m.tool==='stick'?100:30)+button('tool-segment','留下这一段，接着量')+button('tool-unmeasure','取回最后一段')+select('unit','最后用什么单位记录',m.unit,[['cm','厘米 cm'],['m','米 m']]):'')+f('answer',t.mode==='measure'?'物体总长（按选定单位）':'计算得到多少',m.answer);
 case'x-powerbuild':return m.committed===null?f('guess',t.target?'先猜每边几块':'先猜总共几块',m.guess)+button('power-predict','留下猜想，再搭'):(!t.base?range('side','每条边放几块',m.side,1,t.pow===2?8:5):'')+`<div class="b9-actions">${button('power-layer',t.pow===3?'搭满下一层':'铺满下一行')}${t.pow===3?button('turn-extra','↻ 转一转')+button('power-spread',m.spread?'合起各层':'拉开各层'):''}${button('power-factor','把这条边作为一个因子')}${button('power-unfactor','取回最后一个因子')}</div>`+f('total','搭满后一共有几块',m.total)+f('answer',t.target?'找出的边长是多少':'这几个相同的数相乘是多少',m.answer);
 case'x-powerchain':return(m.products.length<t.count?f('next','下一次相乘得到多少',m.next)+button('chain-step','留下这一站'):'')+button('chain-undo','取回最后一站')+(t.add?button('chain-add','再加上 '+t.add,`${m.products.length<t.count?'disabled':''}`):'')+f('answer','整个算式最后是多少',m.answer);
 case'x-rootwindow':return`<div class="b9-fields">${f('low','新的左端',m.low)}${f('high','新的右端',m.high)}</div>`+button('root-test','两端各自平方，检查这一段')+f('exact','怎样写这个精确的数',m.exact)+f('decimal','按三位小数报个大概',m.decimal)+select('relation','1.414 与 √2 是什么关系',m.relation,[['equal','完全相等 ='],['approx','只是近似 ≈']]);
 case'x-decimalmachine':return`<div class="b9-fields">${f('digit','这一轮，每份得到几小份（小数的一位）',m.digit)}${f('remainder','还剩几份，留到下一轮',m.remainder)}</div>`+button('decimal-next','留下这一步')+button('decimal-undo','取回最后一步')+select('kind','这次分份会怎样继续',m.kind,[['ends','余数为0，可以结束'],['repeats','非零余数回来，会重复'],['irrational','写得长，所以不能成为分数']])+f('fraction','给它写一个整数之比',m.fraction);
 case'x-numbercards':return select('kinds.'+m.active,'把这张卡放在哪里',m.kinds[m.active],[['rational','能写成两个整数之比'],['irrational','不能写成两个整数之比']])+f('fractions.'+m.active,'如果能，写一个分数（整数也可写 /1）',m.fractions[m.active])+select('reasons.'+m.active,'依据是什么',m.reasons[m.active],[['ends','有限小数可写成整数分数'],['repeats','余数循环，数字重复，仍能写成分数'],['root9','这个根实际等于3'],['root2','最简分数的假设会出现矛盾'],['pi','已证明的π的性质，本活动不展开证明'],['looks','只看小数写得长或有没有根号']]);
 case'x-betweenpoints':return f('entry','我找到的中间数',m.entry)+button('between-insert','把这个点放进去',m.history.length>=8?'disabled':'')+`<div class="b9-actions">${button('between-zoom','放大左边这一段',`data-side="left" ${!m.pending?'disabled':''}`)}${button('between-zoom','放大右边这一段',`data-side="right" ${!m.pending?'disabled':''}`)}</div>`+select('rule','两端再近，什么办法仍能找中间数',m.rule,[['midpoint','把两端相加再除以2'],['plusone','总给左端加1'],['round','把两端取整']]);
}return'';}
export const render=(t,m)=>`<section class="b9-work">${t.type==='x-powerbuild'&&t.pow===3?'<div id="extra-world" class="cube-world"></div>':''}<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div></section>`;
